let me=null,students=[],config={exams:[],subjects:[],classes:[],resource_categories:[]},charts={};
const $=x=>document.getElementById(x);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
async function api(url,opt={}){let r=await fetch(url,{headers:{"Content-Type":"application/json",...(opt.headers||{})},...opt});let d=await r.json();if(!r.ok)throw Error(d.error||"Request failed");return d}
function toast(s){$("toast").textContent=s;$("toast").style.display="block";setTimeout(()=>$("toast").style.display="none",3200)}
function navigate(p){document.querySelectorAll(".page").forEach(x=>x.classList.toggle("hidden",x.id!==p));document.querySelectorAll("nav button").forEach(x=>x.classList.toggle("active",x.dataset.page===p));if(p==="dashboard")refreshDashboard();if(p==="students")renderStudents();if(p==="results")showResults();if(p==="attendance")showAttendance();if(p==="analytics")refreshAnalytics();if(p==="resources")renderResources();if(p==="settings")loadAdmin()}
let selectedLoginRole="principal";
async function boot(){let st=await api("/api/status");if(st.setup){$("setupScreen").classList.remove("hidden");return}let m=await api("/api/me");if(m.user)await enter(m.user);else{$("loginScreen").classList.remove("hidden");setLoginRole("principal")}}
function setLoginRole(role){selectedLoginRole=role;document.querySelectorAll(".role-tab").forEach(b=>b.classList.toggle("active",b.dataset.role===role));let meta={principal:{title:"Principal sign in",subtitle:"Access the school control centre.",label:"Principal User ID",placeholder:"principal",hint:"The principal manages teacher accounts and school settings."},teacher:{title:"Teacher sign in",subtitle:"Access your teaching workspace.",label:"Teacher User ID",placeholder:"e.g. rahul.sir",hint:"Teacher accounts are created by the principal."},student:{title:"Student sign in",subtitle:"View your academic portal.",label:"Admission No.",placeholder:"e.g. ADM20260125",hint:"Use your Admission No. as the initial username and password."}}[role];$("loginTitle").textContent=meta.title;$("loginSubtitle").textContent=meta.subtitle;$("loginUserLabel").childNodes[0].nodeValue=meta.label;$("loginUser").placeholder=meta.placeholder;$("loginHint").textContent=meta.hint;$("loginError").textContent=""}
document.querySelectorAll(".role-tab").forEach(b=>b.onclick=()=>setLoginRole(b.dataset.role));
document.querySelectorAll(".peek").forEach(b=>b.onclick=()=>{let input=$(b.dataset.target);input.type=input.type==="password"?"text":"password";b.textContent=input.type==="password"?"◉":"◌"});
$("setupForm").onsubmit=async e=>{e.preventDefault();$("setupError").textContent="";let d=Object.fromEntries(new FormData(e.target));if(d.password!==d.confirm_password){$("setupError").textContent="Passwords do not match.";return}try{await api("/api/setup",{method:"POST",body:JSON.stringify(d)});$("setupScreen").classList.add("hidden");$("loginScreen").classList.remove("hidden");setLoginRole("principal");$("loginUser").value=d.username;toast("Principal account created. Sign in as Principal.")}catch(x){$("setupError").textContent=x.message}}
$("loginForm").onsubmit=async e=>{e.preventDefault();$("loginError").textContent="";try{let d=await api("/api/login",{method:"POST",body:JSON.stringify({username:$("loginUser").value,password:$("loginPass").value,role:selectedLoginRole})});let m=await api("/api/me");await enter(m.user);if(d.force_change)openPassword(true)}catch(x){$("loginError").textContent=x.message}}
async function enter(u){me=u;$("loginScreen").classList.add("hidden");$("setupScreen").classList.add("hidden");$("app").classList.remove("hidden");$("userName").textContent=u.name||u.username;updateProfileHeader();$("helloName").textContent=(u.name||u.username).split(" ")[0];$("rolePill").textContent=u.role.toUpperCase();document.querySelectorAll(".principal-only").forEach(x=>x.classList.toggle("hidden",u.role!=="principal"));document.querySelectorAll(".teacher-only").forEach(x=>x.classList.toggle("hidden",u.role==="student"));config=await api("/api/config");populateConfig();students=await api("/api/students");populateBulkMarkChoices();if(u.role==="student"){$("dashboardClass").disabled=true;$("dashboardClass").innerHTML=`<option>${safeClass(students[0])}</option>`;$("studentAttendancePanel").classList.remove("hidden");$("teacherAttendanceWorkspace").classList.add("hidden")}else loadClassChoices();if($("dailyDate"))$("dailyDate").value=new Date().toISOString().slice(0,10);navigate("dashboard")}
function safeClass(s){return s?`${s.class_name}-${s.section}`:"My class"}
function populateConfig(){fillExams();$("markSubject").innerHTML=config.subjects.map(s=>`<option>${esc(s)}</option>`).join("");$("attMonth").innerHTML=Array.from({length:12},(_,i)=>`<option value="${i+1}">${new Date(2000,i).toLocaleString("en",{month:"long"})}</option>`).join("");$("attYear").value=new Date().getFullYear();$("newExam").value=""}
function fillExams(){["resultExam"].forEach(id=>$(id).innerHTML=config.exams.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join(""))}
function loadClassChoices(){let classes=[...new Set(students.map(s=>`${s.class_name}-${s.section}`))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));let saved=localStorage.getItem("edutrack.class");if(!classes.includes(saved))saved=classes[0]||"";$("dashboardClass").innerHTML=`<option value="">All classes</option>`+classes.map(c=>`<option ${c===saved?"selected":""}>${esc(c)}</option>`).join("");$("studentClass").innerHTML=`<option value="">All classes</option>`+Array.from({length:12},(_,i)=>`<option value="${i+1}">Class ${i+1}</option>`).join("");updateSections();loadAttendanceChoices()}
function loadAttendanceChoices(){if(me.role==="student")return;let classes=[...new Set(students.map(s=>s.class_name))].sort((a,b)=>Number(a)-Number(b));$("attClass").innerHTML=classes.map(c=>`<option>${esc(c)}</option>`).join("");$("dailyClass").innerHTML=classes.map(c=>`<option>${esc(c)}</option>`).join("");updateAttendanceSections();let secs=[...new Set(students.filter(s=>s.class_name===$("dailyClass").value).map(s=>s.section))].sort();$("dailySection").innerHTML=secs.map(x=>`<option>${esc(x)}</option>`).join("");if(classes.length){loadAttendanceClass();loadDailyAttendance()}}
$("dashboardClass").onchange=()=>{localStorage.setItem("edutrack.class",$("dashboardClass").value);refreshDashboard();refreshAnalytics()}
$("studentClass").onchange=updateSections;$("studentSection").onchange=renderStudents;
function updateSections(){let cl=$("studentClass").value;let secs=[...new Set(students.filter(s=>!cl||s.class_name===cl).map(s=>s.section))].sort();$("studentSection").innerHTML=`<option value="">All sections</option>`+secs.map(s=>`<option>${esc(s)}</option>`).join("");renderStudents()}
function selectedStudents(){let c=$("dashboardClass").value;if(!c)return students;let [cl,sec]=c.split("-");return students.filter(s=>s.class_name===cl&&s.section===sec)}
async function analyticsFor(list){if(me.role==="student")return api("/api/analytics");let ids=list.map(s=>s.id);if(!ids.length)return {average:null,attendance:null,subject:{},exam:{}};let ms=(await Promise.all(ids.map(id=>api("/api/marks/"+id)))).flat();let ats=(await Promise.all(ids.map(id=>api("/api/attendance/"+id)))).flat();let avg=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:0;let subject={},exam={};ms.forEach(m=>{let p=m.max_score?m.score/m.max_score*100:0;(subject[m.subject]??=[]).push(p);(exam[m.exam]??=[]).push(p)});let work=ats.reduce((a,x)=>a+x.working_days,0),present=ats.reduce((a,x)=>a+x.present_days,0);return {average:ms.length?avg(ms.map(m=>m.score/m.max_score*100)):null,attendance:work?present/work*100:null,subject:Object.fromEntries(Object.entries(subject).map(([k,v])=>[k,avg(v)])),exam:Object.fromEntries(Object.entries(exam).map(([k,v])=>[k,avg(v)]))}}
function chart(id,type,labels,data,opts={}){if(charts[id])charts[id].destroy();charts[id]=new Chart($(id),{type,data:{labels,datasets:[{data,backgroundColor:type==="doughnut"?["#6556ee","#18bfa9","#f0ae54","#789af7","#9d85ed"]:"#6556ee",borderColor:"#6556ee",borderRadius:7,tension:.35,fill:type==="line"}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:type==="doughnut"}},scales:type==="doughnut"?{}:{y:{beginAtZero:true,max:100,grid:{color:"#eef0f5"}},x:{grid:{display:false}}},...opts}})}
async function refreshDashboard(){let ss=selectedStudents(),a=await analyticsFor(ss);$("dStudents").textContent=ss.length;$("dAverage").textContent=a.average!=null?a.average.toFixed(1)+"%":"—";$("dAttendance").textContent=a.attendance!=null?a.attendance.toFixed(1)+"%":"—";$("dExams").textContent=config.exams.length;let sub=config.subjects.filter(s=>a.subject[s]!=null),vals=sub.map(s=>a.subject[s]);chart("subjectChart","bar",sub,vals);let ex=config.exams.filter(e=>a.exam[e.name]!=null);chart("examChart","line",ex.map(e=>e.name),ex.map(e=>a.exam[e.name]),{scales:{y:{beginAtZero:true,max:100}}})}
function renderStudents(){if(!me)return;let q=($("studentSearch")?.value||"").toLowerCase(),cl=$("studentClass")?.value||"",sec=$("studentSection")?.value||"";let base=me.role==="student"?students.filter(s=>s.id===me.student_id):students;let ss=base.filter(s=>(!q||`${s.name} ${s.admission_no} ${s.roll}`.toLowerCase().includes(q))&&(!cl||s.class_name===cl)&&(!sec||s.section===sec));$("studentTable").innerHTML=ss.map(s=>`<tr class="reveal"><td><b>${esc(s.name)}</b><small>${esc(s.father_name||"")}</small></td><td><strong>${esc(s.admission_no)}</strong></td><td>${s.class_name}-${s.section}</td><td>${s.roll}</td><td><button class="tiny" data-att="${s.id}">Attendance</button></td><td><button class="tiny" data-result="${s.id}">Results</button>${me.role!=="student"?` <button class="tiny" data-edit="${s.id}">Edit</button> <button class="tiny danger" data-delete="${s.id}">Delete</button>`:""}</td></tr>`).join("")||`<tr><td colspan="6">No matching students.</td></tr>`;document.querySelectorAll("[data-result]").forEach(b=>b.onclick=()=>{navigate("results");$("resultStudent").value=b.dataset.result;showResults()});document.querySelectorAll("[data-att]").forEach(b=>b.onclick=()=>{navigate("attendance");if(me.role!=="student"){let st=students.find(x=>x.id===Number(b.dataset.att));if(st){$("attClass").value=st.class_name;updateAttendanceSections(st.section);$("attSection").value=st.section;loadAttendanceClass()}}});document.querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>openEditStudent(Number(b.dataset.edit)));document.querySelectorAll("[data-delete]").forEach(b=>b.onclick=async()=>{if(confirm("Delete this student and all linked records?")){await api("/api/students/"+b.dataset.delete,{method:"DELETE"});students=await api("/api/students");loadClassChoices();toast("Student deleted")}})}
$("studentSearch").oninput=renderStudents;
async function loadResultStudents(){let list=me.role==="student"?students:students;$("resultStudent").innerHTML=list.map(s=>`<option value="${s.id}">${esc(s.name)} • ${esc(s.admission_no)}</option>`).join("");if(me.role==="student")$("resultStudent").disabled=true}
async function showResults(){await loadResultStudents();let sid=$("resultStudent").value;if(!sid)return;let ms=await api("/api/marks/"+sid),eid=Number($("resultExam").value),ex=config.exams.find(e=>e.id===eid);let rows=ms.filter(m=>m.exam_id===eid);let sum=rows.reduce((a,m)=>a+m.score,0),max=rows.reduce((a,m)=>a+m.max_score,0);$("marksTable").innerHTML=rows.map(m=>`<tr><td>${esc(m.subject)}</td><td>${m.score}</td><td>${m.max_score}</td><td><b>${(m.score/m.max_score*100).toFixed(1)}%</b></td></tr>`).join("")||`<tr><td colspan="4">No marks entered for ${esc(ex?.name||"this exam")}.</td></tr>`;if(max)$("marksTable").insertAdjacentHTML("beforebegin",`<tr class="total"><td><b>EXAM TOTAL</b></td><td><b>${sum}</b></td><td><b>${max}</b></td><td><b>${(sum/max*100).toFixed(1)}%</b></td></tr>`)}
$("resultStudent").onchange=showResults;$("resultExam").onchange=showResults;
function populateBulkMarkChoices(){
 if(!$('bulkMarkClass'))return;
 let classes=[...new Set(students.map(s=>s.class_name))].sort((a,b)=>Number(a)-Number(b));
 $('bulkMarkClass').innerHTML=classes.map(c=>`<option value="${esc(c)}">Class ${esc(c)}</option>`).join('');
 fillBulkSections();
 $('bulkMarkExam').innerHTML=config.exams.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');
 $('bulkMarkSubject').innerHTML=config.subjects.map(s=>`<option>${esc(s)}</option>`).join('');
}
function fillBulkSections(){let cl=$('bulkMarkClass')?.value||'';let secs=[...new Set(students.filter(s=>s.class_name===cl).map(s=>s.section))].sort();if($('bulkMarkSection'))$('bulkMarkSection').innerHTML=secs.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');}
async function loadBulkMarks(){try{let cl=$('bulkMarkClass').value,sec=$('bulkMarkSection').value,eid=Number($('bulkMarkExam').value),sub=$('bulkMarkSubject').value;if(!cl||!sec||!eid||!sub){toast('Select class, section, examination and subject.');return;}let list=students.filter(s=>s.class_name===cl&&s.section===sec).sort((a,b)=>Number(a.roll)-Number(b.roll));let all=await Promise.all(list.map(async s=>({s,marks:await api(`/api/marks/${s.id}`)})));let mx=Number($('bulkMarkMax').value)||100;$('bulkMarksTable').innerHTML=all.map(x=>{let m=x.marks.find(m=>Number(m.exam_id)===eid&&m.subject===sub);let score=m?.score??'';let rowmx=m?Number(m.max_score)||mx:mx;return `<tr data-student-id="${x.s.id}"><td>${esc(x.s.roll)}</td><td>${esc(x.s.admission_no)}</td><td><b>${esc(x.s.name)}</b></td><td><input class="bulk-score" type="number" min="0" max="${rowmx}" step="0.01" value="${score}" placeholder="—"></td><td class="bulk-max">${rowmx}</td><td class="bulk-pct">${score===''?'—':(Number(score)/rowmx*100).toFixed(1)+'%'}</td></tr>`}).join('')||`<tr><td colspan="6">No students found in ${esc(cl)}-${esc(sec)}.</td></tr>`;document.querySelectorAll('.bulk-score').forEach(inp=>inp.addEventListener('input',()=>{let tr=inp.closest('tr'),mx=Number($('bulkMarkMax').value)||100,val=inp.value;tr.querySelector('.bulk-max').textContent=mx;tr.querySelector('.bulk-pct').textContent=val===''?'—':(Number(val)/mx*100).toFixed(1)+'%'}));$('bulkMarkSummary').textContent=`${list.length} students • ${sub} • ${config.exams.find(e=>e.id===eid)?.name||'Exam'}`;}catch(e){toast(e.message)}}
async function saveBulkMarks(){try{let eid=Number($('bulkMarkExam').value),sub=$('bulkMarkSubject').value,mx=Number($('bulkMarkMax').value);if(!eid||!sub||!mx){toast('Select examination, subject and maximum marks.');return;}let inputs=[...document.querySelectorAll('#bulkMarksTable .bulk-score')],marks=[];for(let input of inputs){if(input.value==='')continue;let score=Number(input.value),sid=Number(input.closest('tr').dataset.studentId);if(!Number.isFinite(score)||score<0||score>mx){toast(`Enter marks between 0 and ${mx}.`);input.focus();return}marks.push({student_id:sid,score});}if(!marks.length){toast('Enter at least one mark.');return;}let d=await api('/api/marks/bulk',{method:'POST',body:JSON.stringify({exam_id:eid,subject:sub,max_score:mx,marks})});toast(`${d.saved} student marks saved successfully`);showResults();refreshDashboard();}catch(e){toast(e.message)}}
$("saveMark").onclick=async()=>{try{await api("/api/marks",{method:"POST",body:JSON.stringify({student_id:$("resultStudent").value,exam_id:$("resultExam").value,subject:$("markSubject").value,score:$("markScore").value,max_score:$("markMax").value})});toast("Mark saved");showResults();refreshDashboard()}catch(e){toast(e.message)}};
function updateAttendanceSections(preferred=""){let cl=$("attClass").value;let secs=[...new Set(students.filter(s=>s.class_name===cl).map(s=>s.section))].sort();$("attSection").innerHTML=secs.map(x=>`<option>${esc(x)}</option>`).join("");if(preferred&&secs.includes(preferred))$("attSection").value=preferred}
async function loadAttendanceClass(){if(me.role==="student")return;let cl=$("attClass").value,sec=$("attSection").value;if(!cl||!sec){$("bulkAttendanceList").innerHTML='<div class="empty-state">Choose a class and section first.</div>';return}let y=Number($("attYear").value),m=Number($("attMonth").value),d=await api(`/api/attendance/class?class_name=${encodeURIComponent(cl)}&section=${encodeURIComponent(sec)}&year=${y}&month=${m}`);let existing=d.students.find(s=>Number(s.working_days)>0);if(existing)$("workingDays").value=existing.working_days;let wd=Number($("workingDays").value||0),present=d.students.reduce((a,s)=>a+Number(s.present_days||0),0),totalPossible=wd*d.students.length;$("attStatWorking").textContent=wd;$("attStatStudents").textContent=d.students.length;$("attStatPresent").textContent=present;$("attStatAbsent").textContent=wd?Math.max(0,totalPossible-present):0;$("attStatPercent").textContent=totalPossible?(present/totalPossible*100).toFixed(1)+"%":"—";$("bulkAttendanceList").innerHTML=d.students.map((s,i)=>`<div class="attendance-row"><div class="student-index">${String(i+1).padStart(2,"0")}</div><div class="student-info"><b>${esc(s.name)}</b><small>${esc(s.admission_no)} • Roll ${s.roll}</small></div><div class="present-input"><label>Present days<input class="bulk-present" data-id="${s.id}" type="number" min="0" max="${wd||999}" value="${s.present_days||0}"></label></div><div class="live-percent" data-pct="${s.id}">${s.percentage!=null?s.percentage+"%":"—"}</div></div>`).join("")||'<div class="empty-state">No students in this class-section.</div>';document.querySelectorAll(".bulk-present").forEach(i=>i.oninput=updateMonthlyStats);$("bulkAttendanceSummary").textContent=`${d.students.length} students loaded • ${wd||0} working days`;await loadDailyHistory()}
function updateMonthlyStats(){let inputs=[...document.querySelectorAll(".bulk-present")],wd=Number($("workingDays").value||0),present=inputs.reduce((a,i)=>a+Number(i.value||0),0),studentsCount=inputs.length,total=wd*studentsCount;inputs.forEach(i=>{let pd=Number(i.value||0),pct=wd&&pd<=wd?(pd/wd*100).toFixed(1)+"%":"—";let el=document.querySelector(`[data-pct="${i.dataset.id}"]`);if(el)el.textContent=pct});$("attStatWorking").textContent=wd;$("attStatStudents").textContent=studentsCount;$("attStatPresent").textContent=present;$("attStatAbsent").textContent=wd?Math.max(0,total-present):0;$("attStatPercent").textContent=total?(present/total*100).toFixed(1)+"%":"—";$("bulkAttendanceSummary").textContent=`${studentsCount} students loaded • ${wd||0} working days`}
async function loadDailyHistory(){if(me.role==="student")return;let cl=$("attClass").value,sec=$("attSection").value,y=Number($("attYear").value),m=Number($("attMonth").value);if(!cl||!sec||!y||!m)return;let from=`${y}-${String(m).padStart(2,"0")}-01`,last=new Date(y,m,0).getDate(),to=`${y}-${String(m).padStart(2,"0")}-${String(last).padStart(2,"0")}`;let d=await api(`/api/attendance/daily/class/summary?class_name=${encodeURIComponent(cl)}&section=${encodeURIComponent(sec)}&from=${from}&to=${to}`);$("dailyHistoryTable").innerHTML=d.days.map(r=>`<tr><td>${new Date(r.attendance_date+"T00:00:00").toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"})}</td><td>${new Date(r.attendance_date+"T00:00:00").toLocaleDateString("en-IN",{weekday:"short"})}</td><td><b>${r.present}</b></td><td>${r.absent}</td><td>${r.marked}</td><td><b>${r.rate}%</b></td></tr>`).join("")||`<tr><td colspan="6">No daily attendance has been marked for this month.</td></tr>`}
async function renderStaffMonthlyHistory(){if(me.role==="student")return;let rows=await Promise.all(students.map(s=>api(`/api/attendance/${s.id}`))),map={};rows.flat().forEach(r=>{let k=`${r.year}-${String(r.month).padStart(2,"0")}`;map[k]??={year:r.year,month:r.month,working_days:Number(r.working_days||0),present_days:0,students:0};map[k].present_days+=Number(r.present_days||0);map[k].working_days=Math.max(map[k].working_days,Number(r.working_days||0));map[k].students+=1});let out=Object.values(map).sort((a,b)=>b.year-a.year||b.month-a.month);$("attendanceTable").innerHTML=out.map(r=>{let possible=r.working_days*r.students,pct=possible?r.present_days/possible*100:0,abs=Math.max(0,possible-r.present_days);return `<tr><td>${new Date(r.year,r.month-1,1).toLocaleString("en",{month:"long",year:"numeric"})}</td><td>${r.working_days}</td><td>${r.present_days}</td><td>${abs}</td><td><b>${pct.toFixed(1)}%</b></td></tr>`}).join("")||`<tr><td colspan="5">No monthly attendance recorded.</td></tr>`}
async function showAttendance(){if(me.role==="student"){let d=await api("/api/attendance/student/"+me.student_id+"/summary"),pct=d.percentage==null?"—":d.percentage+"%";$("studentAttendancePanel").classList.remove("hidden");$("studentAttPercent").textContent=pct;$("studentAttRing").textContent=pct;$("studentAttPresent").textContent=d.present_days;$("studentAttAbsent").textContent=d.absent_days;$("studentAttTotal").textContent=d.total_days;$("studentAbsenceTable").innerHTML=d.absences.map(r=>`<tr><td>${new Date(r.attendance_date+"T00:00:00").toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"})}</td><td><span class="absence-pill">Absent</span></td></tr>`).join("")||`<tr><td colspan="2">No absences recorded. Great!</td></tr>`;$("attendanceTable").innerHTML=d.monthly.map(r=>`<tr><td>${new Date(r.year,r.month-1).toLocaleString("en",{month:"long",year:"numeric"})}</td><td>${r.working_days}</td><td>${r.present_days}</td><td>${Math.max(0,r.working_days-r.present_days)}</td><td><b>${r.percentage}%</b></td></tr>`).join("")||`<tr><td colspan="5">No monthly attendance recorded.</td></tr>`;return}if($("attClass").value)await loadAttendanceClass();await loadDailyAttendance();await renderStaffMonthlyHistory()}
async function loadDailyAttendance(){if(me.role==="student")return;let cl=$("dailyClass").value,sec=$("dailySection").value,date=$("dailyDate").value;if(!cl||!sec||!date){$("dailyAttendanceList").innerHTML='<div class="empty-state">Choose a class, section and date.</div>';return}let d=await api(`/api/attendance/daily/class?class_name=${encodeURIComponent(cl)}&section=${encodeURIComponent(sec)}&date=${encodeURIComponent(date)}`);$("dailyAttendanceList").innerHTML=d.students.map((st,i)=>`<div class="daily-att-row ${st.status==='present'?'is-present':''}"><div class="student-index">${String(i+1).padStart(2,'0')}</div><div class="student-info"><b>${esc(st.name)}</b><small>${esc(st.admission_no)} • Roll ${st.roll}</small></div><div class="status-actions"><button class="status-btn present ${st.status==='present'?'active':''}" data-daily-id="${st.id}" data-status="present">✓ Present</button><button class="status-btn absent ${st.status==='absent'?'active':''}" data-daily-id="${st.id}" data-status="absent">Absent</button></div></div>`).join('')||'<div class="empty-state">No students in this class-section.</div>';document.querySelectorAll('[data-daily-id]').forEach(b=>b.onclick=()=>setDailyStatus(b.dataset.dailyId,b.dataset.status));updateDailySummary()}
function setDailyStatus(id,status){document.querySelectorAll(`[data-daily-id="${id}"]`).forEach(b=>b.classList.toggle('active',b.dataset.status===status));let row=document.querySelector(`[data-daily-id="${id}"]`)?.closest('.daily-att-row');if(row)row.classList.toggle('is-present',status==='present');updateDailySummary()}
function updateDailySummary(){let rows=[...document.querySelectorAll('.daily-att-row')],present=rows.filter(r=>r.classList.contains('is-present')).length;$("dailySummary").textContent=`${present}/${rows.length} present • ${rows.length-present} absent`}
$("dailyClass").onchange=()=>{let cl=$("dailyClass").value;let secs=[...new Set(students.filter(s=>s.class_name===cl).map(s=>s.section))].sort();$("dailySection").innerHTML=secs.map(x=>`<option>${esc(x)}</option>`).join('');loadDailyAttendance()};$("dailySection").onchange=loadDailyAttendance;$("dailyDate").onchange=loadDailyAttendance;$("loadDailyAttendance").onclick=loadDailyAttendance;$("markAllPresent").onclick=()=>{document.querySelectorAll('.daily-att-row').forEach(r=>setDailyStatus(r.querySelector('[data-status="present"]').dataset.dailyId,'present'))};$("saveDailyAttendance").onclick=async()=>{let rows=[...document.querySelectorAll('.daily-att-row')],cl=$("dailyClass").value,sec=$("dailySection").value,date=$("dailyDate").value;if(!rows.length){toast('Load a class first.');return}try{let records=rows.map(r=>{let b=r.querySelector('.status-btn.active');return{id:b.dataset.dailyId,status:b.dataset.status}});let out=await api('/api/attendance/daily/bulk',{method:'POST',body:JSON.stringify({class_name:cl,section:sec,date,records})});toast(`${out.saved} daily attendance records saved`);await loadDailyAttendance();refreshDashboard()}catch(e){toast(e.message)}};
document.querySelectorAll(".attendance-tab").forEach(tab=>tab.onclick=async()=>{document.querySelectorAll(".attendance-tab").forEach(x=>x.classList.toggle("active",x===tab));let monthly=tab.dataset.attTab==="monthly";$("dailyAttendanceTab").classList.toggle("hidden",monthly);$("monthlyAttendanceTab").classList.toggle("hidden",!monthly);if(monthly){await loadAttendanceClass();await renderStaffMonthlyHistory()}else await loadDailyAttendance()});
$("attClass").onchange=()=>{updateAttendanceSections();loadAttendanceClass()};$("attSection").onchange=loadAttendanceClass;$("attYear").onchange=loadAttendanceClass;$("attMonth").onchange=loadAttendanceClass;$("workingDays").oninput=updateMonthlyStats;$("refreshDailyHistory")?.addEventListener("click",loadDailyHistory);$("loadAttendanceClass").onclick=loadAttendanceClass;$("saveBulkAttendance").onclick=async()=>{let wd=Number($("workingDays").value),cl=$("attClass").value,sec=$("attSection").value;if(!wd||!cl||!sec){toast("Choose class, section and working days.");return}let records=[...document.querySelectorAll(".bulk-present")].map(i=>({id:i.dataset.id,present_days:Number(i.value||0)}));try{let out=await api("/api/attendance/bulk",{method:"POST",body:JSON.stringify({class_name:cl,section:sec,year:Number($("attYear").value),month:Number($("attMonth").value),working_days:wd,records})});toast(`${out.saved} attendance records saved`);await loadAttendanceClass();await renderStaffMonthlyHistory();refreshDashboard()}catch(e){toast(e.message)}};
