function avatarMarkup(u,size="sm"){
 const name=esc((u?.name||u?.username||"U").trim());
 if(u?.avatar_url) return `<img class="profile-avatar ${size}" src="${esc(u.avatar_url)}?v=${Date.now()}" alt="${name}">`;
 return `<span class="profile-avatar ${size} fallback">${esc((u?.name||u?.username||"U").charAt(0).toUpperCase())}</span>`;
}
function updateProfileHeader(){
 const menu=$("userMenu"); if(!menu||!me)return;
 menu.innerHTML=`${avatarMarkup(me,"sm")}<span id="userName">${esc(me.name||me.username)}</span><span class="user-chevron">⌄</span>`;
}
async function refreshMe(){
 const m=await api("/api/me"); if(m.user){me=m.user;updateProfileHeader();$("helloName").textContent=(me.name||me.username).split(" ")[0];}
}
async function openProfileModal(){
 try{
  const p=(await api("/api/profile")).profile;
  const isStudent=me.role==="student";
  $("modalContent").innerHTML=`<div class="profile-modal">
   <div class="profile-cover"><div class="profile-avatar-wrap">${avatarMarkup(p,"lg")}<label class="avatar-upload" title="Change profile picture">＋<input id="profileAvatarInput" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label></div>
    <div><div class="eyebrow">PROFILE</div><h2>Edit profile</h2><p>${isStudent?"Keep your personal and contact details up to date.":"Update your account details and profile picture."}</p></div>
   </div>
   <form id="profileForm">
    <div class="two">
      <label>Full name<input name="name" required value="${esc(p.name||"")}"></label>
      <label>Email<input name="email" type="email" value="${esc(p.email||"")}" placeholder="name@example.com"></label>
      <label>Phone<input name="phone" value="${esc(p.phone||"")}" placeholder="Phone number"></label>
      <label>Date of birth<input name="dob" type="date" value="${esc(p.dob||"")}"></label>
      ${isStudent?`<label>Gender<input name="gender" value="${esc(p.gender||"")}"></label><label>Father's name<input name="father_name" value="${esc(p.father_name||"")}"></label><label>Mother's name<input name="mother_name" value="${esc(p.mother_name||"")}"></label>`:""}
    </div>
    <div class="profile-readonly"><span><small>USER ID</small><b>${esc(p.username)}</b></span><span><small>ROLE</small><b>${esc(String(p.role).toUpperCase())}</b></span>${isStudent?`<span><small>CLASS</small><b>${esc(p.class_name)}-${esc(p.section)}</b></span>`:""}</div>
    <div id="profileError" class="error"></div>
    <button class="btn primary full">Save profile</button>
   </form>
  </div>`;
  $("modal").classList.remove("hidden");
  $("profileForm").onsubmit=async e=>{
   e.preventDefault();
   try{
    const data=Object.fromEntries(new FormData(e.target));
    await api("/api/profile",{method:"PUT",body:JSON.stringify(data)});
    const file=$("profileAvatarInput")?.files?.[0];
    if(file){
      if(file.size>4*1024*1024) throw Error("Profile image must be 4 MB or smaller.");
      const fd=new FormData();fd.append("avatar",file);
      await api("/api/profile/avatar",{method:"POST",body:fd});
    }
    await refreshMe(); $("modal").classList.add("hidden"); toast("Profile updated");
   }catch(x){$("profileError").textContent=x.message}
  };
  $("profileAvatarInput").onchange=e=>{
   const f=e.target.files?.[0]; if(!f)return;
   if(f.size>4*1024*1024){$("profileError").textContent="Profile image must be 4 MB or smaller.";return}
   const img=document.querySelector(".profile-avatar.lg");
   if(img && f.type.startsWith("image/")) img.src=URL.createObjectURL(f);
  };
 }catch(e){toast(e.message)}
}
