function openEditStudent(id){let s=students.find(x=>x.id===id);if(!s)return;let fields=`<div class="eyebrow">STUDENT PROFILE</div><h2>Edit student</h2><p>Update the student's details. Changing Admission No. also changes their login username.</p><form id="editStudentForm"><div class="two"><label>Full name<input name="name" required value="${esc(s.name)}"></label><label>Admission No.<input name="admission_no" required value="${esc(s.admission_no)}"></label><label>Class<select name="class_name">${Array.from({length:12},(_,i)=>`<option ${String(i+1)===String(s.class_name)?"selected":""}>${i+1}</option>`).join("")}</select></label><label>Section<input name="section" required value="${esc(s.section)}"></label><label>Roll No.<input name="roll" type="number" min="1" required value="${s.roll}"></label><label>Gender<input name="gender" value="${esc(s.gender||"")}"></label><label>Date of birth<input name="dob" type="date" value="${esc(s.dob||"")}"></label><label>Father's name<input name="father_name" value="${esc(s.father_name||"")}"></label><label>Mother's name<input name="mother_name" value="${esc(s.mother_name||"")}"></label><label>Phone<input name="phone" value="${esc(s.phone||"")}"></label><label>Email<input name="email" type="email" value="${esc(s.email||"")}"></label></div><button class="btn primary full">Save changes</button></form><div id="modalError" class="error"></div>`;$("modalContent").innerHTML=fields;$("modal").classList.remove("hidden");$("editStudentForm").onsubmit=async e=>{e.preventDefault();try{await api("/api/students/"+id,{method:"PUT",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});students=await api("/api/students");loadClassChoices();$("modal").classList.add("hidden");toast("Student details updated")}catch(x){$("modalError").textContent=x.message}}}

