const themeKey="edutrack.theme";function applyTheme(t){document.body.classList.toggle("dark",t==="dark");$("themeToggle").textContent=t==="dark"?"☀":"☾";localStorage.setItem(themeKey,t)}applyTheme(localStorage.getItem(themeKey)||"light");$("themeToggle").onclick=()=>applyTheme(document.body.classList.contains("dark")?"light":"dark");
let navStack=[];const originalNavigate=navigate;navigate=function(p){let current=document.querySelector(".page:not(.hidden)")?.id;if(current&&current!==p)navStack.push(current);originalNavigate(p);window.scrollTo({top:0,behavior:"smooth"})};$("backBtn").onclick=()=>{let prev=navStack.pop();if(prev)originalNavigate(prev);else toast("You're at the first page")};window.addEventListener("popstate",()=>{let prev=navStack.pop();if(prev)originalNavigate(prev)});
const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add("visible")}),{threshold:.08});function observeReveals(){document.querySelectorAll(".card,.kpis>div,.hero,.heading-row,.reveal,.attendance-row").forEach(e=>{if(!e.dataset.reveal){e.dataset.reveal="1";revealObserver.observe(e)}})}new MutationObserver(observeReveals).observe(document.body,{subtree:true,childList:true});observeReveals();

/* ---------- PRINT / REPORT CENTRE ---------- */
function printWindow(title, body, landscape=false){
 const w=window.open("","_blank","width=1100,height=800");
 if(!w){toast("Allow pop-ups to print reports.");return}
 const css=`@page{size:${landscape?"A4 landscape":"A4"};margin:12mm}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#111;margin:0;background:#fff;font-size:12px}.report{max-width:1000px;margin:0 auto}.school{text-align:center;border-bottom:2px solid #111;padding-bottom:10px;margin-bottom:12px}.school h1{font-size:22px;margin:0 0 4px}.school h2{font-size:15px;margin:0 0 4px}.school p{margin:2px 0;color:#444}.title{text-align:center;font-size:18px;font-weight:700;margin:12px 0;text-transform:uppercase}.draft{display:inline-block;border:2px solid #111;padding:4px 12px;margin-bottom:8px;font-weight:700}.meta{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;border:1px solid #222;padding:8px;margin-bottom:12px}.meta div{padding:3px}.meta b{display:block;font-size:10px;text-transform:uppercase;color:#555;margin-bottom:2px}table{width:100%;border-collapse:collapse;margin:8px 0 14px}th,td{border:1px solid #333;padding:7px 6px;text-align:left}th{font-weight:700;background:#eee;text-transform:uppercase;font-size:10px}td.num,th.num{text-align:center}tfoot td{font-weight:700}.summary{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid #333;margin:12px 0}.summary div{padding:8px;border-right:1px solid #333;text-align:center}.summary div:last-child{border-right:0}.summary b{display:block;font-size:10px;color:#555}.summary strong{font-size:16px}.remarks{border:1px solid #333;padding:10px;min-height:50px}.signatures{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin-top:55px;text-align:center}.signatures div{border-top:1px solid #222;padding-top:5px}.footer{margin-top:15px;font-size:9px;color:#666;display:flex;justify-content:space-between}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}`;
 w.document.write(`<!doctype html><html><head><title>${esc(title)}</title><style>${css}</style></head><body><div class="report">${body}</div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close();
}
function reportHeader(title,subtitle=""){return `<div class="school"><h1>EduTrack Academic</h1><h2>Academic Intelligence Portal</h2><p>${esc(subtitle)}</p></div><div class="title">${esc(title)}</div>`}
function studentMeta(s){return `<div class="meta"><div><b>Student</b>${esc(s?.name||"—")}</div><div><b>Admission No.</b>${esc(s?.admission_no||"—")}</div><div><b>Class / Section</b>${esc(s?`${s.class_name}-${s.section}`:"—")}</div><div><b>Roll No.</b>${esc(s?.roll??"—")}</div></div>`}
function gradeFor(p){return p>=91?"A1":p>=81?"A2":p>=71?"B1":p>=61?"B2":p>=51?"C1":p>=41?"C2":p>=33?"D":"E"}
function marksSummary(rows){const total=rows.reduce((a,r)=>a+Number(r.score||0),0),max=rows.reduce((a,r)=>a+Number(r.max_score||0),0),pct=max?total/max*100:0;return{total,max,pct,grade:gradeFor(pct)}}
async function printAcademicReport(){try{const sid=Number($("resultStudent").value),eid=Number($("resultExam").value),s=students.find(x=>x.id===sid),ex=config.exams.find(x=>x.id===eid);if(!s||!ex){toast("Select a student and examination first.");return}const rows=(await api(`/api/marks/${sid}`)).filter(x=>Number(x.exam_id)===eid),sum=marksSummary(rows),at=await api(`/api/attendance/${sid}`),work=at.reduce((a,x)=>a+Number(x.working_days||0),0),pres=at.reduce((a,x)=>a+Number(x.present_days||0),0),ap=work?pres/work*100:0;const body=reportHeader("Academic Performance Report",ex.name)+studentMeta(s)+`<table><thead><tr><th>Subject</th><th class="num">Marks</th><th class="num">Maximum</th><th class="num">Percentage</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.subject)}</td><td class="num">${r.score}</td><td class="num">${r.max_score}</td><td class="num">${(r.score/r.max_score*100).toFixed(1)}%</td></tr>`).join("")||`<tr><td colspan="4">No marks entered.</td></tr>`}</tbody></table><div class="summary"><div><b>Total</b><strong>${sum.total.toFixed(1)} / ${sum.max.toFixed(1)}</strong></div><div><b>Percentage</b><strong>${sum.pct.toFixed(1)}%</strong></div><div><b>Grade</b><strong>${sum.grade}</strong></div><div><b>Attendance</b><strong>${ap.toFixed(1)}%</strong></div></div><div class="remarks"><b>Remarks:</b> ${sum.pct>=33?"Satisfactory academic performance.":"Needs academic improvement."}</div><div class="signatures"><div>Class Teacher</div><div>Principal</div><div>Parent / Guardian</div></div>`;printWindow("Academic Performance Report",body)}catch(e){toast(e.message)}}
async function printDraftMarksheet(){try{const sid=Number($("resultStudent").value),eid=Number($("resultExam").value),s=students.find(x=>x.id===sid),ex=config.exams.find(x=>x.id===eid);if(!s||!ex){toast("Select a student and examination first.");return}const rows=(await api(`/api/marks/${sid}`)).filter(x=>Number(x.exam_id)===eid),sum=marksSummary(rows),at=await api(`/api/attendance/${sid}`),work=at.reduce((a,x)=>a+Number(x.working_days||0),0),pres=at.reduce((a,x)=>a+Number(x.present_days||0),0),ap=work?pres/work*100:0;const body=reportHeader("Draft / Phase Result Marksheet",ex.name)+`<div style="text-align:center"><span class="draft">DRAFT / PROVISIONAL — NOT AN OFFICIAL CBSE MARKSHEET</span></div>`+studentMeta(s)+`<table><thead><tr><th>Subject</th><th class="num">Maximum Marks</th><th class="num">Marks Obtained</th><th class="num">Grade</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.subject)}</td><td class="num">${r.max_score}</td><td class="num">${r.score}</td><td class="num">${gradeFor(r.max_score?r.score/r.max_score*100:0)}</td></tr>`).join("")||`<tr><td colspan="4">No marks entered.</td></tr>`}</tbody><tfoot><tr><td>Total</td><td class="num">${sum.max.toFixed(1)}</td><td class="num">${sum.total.toFixed(1)}</td><td class="num">${sum.grade}</td></tr></tfoot></table><div class="summary"><div><b>Percentage</b><strong>${sum.pct.toFixed(1)}%</strong></div><div><b>Overall Grade</b><strong>${sum.grade}</strong></div><div><b>Attendance</b><strong>${ap.toFixed(1)}%</strong></div><div><b>Result</b><strong>${sum.pct>=33?"PASS":"NEEDS IMPROVEMENT"}</strong></div></div><div class="signatures"><div>Class Teacher</div><div>Principal</div><div>Parent / Guardian</div></div>`;printWindow("Draft Result Marksheet",body)}catch(e){toast(e.message)}}
async function printClassResult(){try{let filter=$("dashboardClass").value||"",[cl,sec]=filter.split("-");if(!cl){let s=students[0];if(!s){toast("No students available.");return}cl=s.class_name;sec=s.section}let eid=Number($("resultExam").value),ex=config.exams.find(x=>x.id===eid),list=students.filter(s=>s.class_name===cl&&s.section===sec);if(!list.length){toast("No students in this class-section.");return}let data=await Promise.all(list.map(async s=>({s,rows:(await api(`/api/marks/${s.id}`)).filter(x=>Number(x.exam_id)===eid)})));data=data.map(x=>({...x,z:marksSummary(x.rows)})).sort((a,b)=>b.z.pct-a.z.pct);let body=reportHeader("Class Result Report",`${cl}-${sec} • ${ex?.name||"Examination"}`)+`<table><thead><tr><th>Rank</th><th>Admission No.</th><th>Student</th><th class="num">Total</th><th class="num">Maximum</th><th class="num">Percentage</th><th class="num">Grade</th></tr></thead><tbody>${data.map((x,i)=>`<tr><td class="num">${i+1}</td><td>${esc(x.s.admission_no)}</td><td>${esc(x.s.name)}</td><td class="num">${x.z.total.toFixed(1)}</td><td class="num">${x.z.max.toFixed(1)}</td><td class="num">${x.z.pct.toFixed(1)}%</td><td class="num">${x.z.grade}</td></tr>`).join("")}</tbody></table>`;printWindow("Class Result Report",body,true)}catch(e){toast(e.message)}}
async function printAttendanceReport(){try{const sid=Number($("resultStudent").value)||me?.student_id,s=students.find(x=>x.id===sid);if(!s){toast("Select a student first.");return}const rows=await api(`/api/attendance/${sid}`),w=rows.reduce((a,x)=>a+Number(x.working_days||0),0),p=rows.reduce((a,x)=>a+Number(x.present_days||0),0),ap=w?p/w*100:0;const body=reportHeader("Student Attendance Report")+studentMeta(s)+`<table><thead><tr><th>Month</th><th class="num">Working Days</th><th class="num">Present</th><th class="num">Absent</th><th class="num">Attendance</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${new Date(2000,r.month-1,1).toLocaleString("en",{month:"long"})} ${r.year}</td><td class="num">${r.working_days}</td><td class="num">${r.present_days}</td><td class="num">${Math.max(0,r.working_days-r.present_days)}</td><td class="num">${r.percentage}%</td></tr>`).join("")||`<tr><td colspan="5">No monthly attendance recorded.</td></tr>`}</tbody></table><div class="summary"><div><b>Working Days</b><strong>${w}</strong></div><div><b>Present</b><strong>${p}</strong></div><div><b>Absent</b><strong>${Math.max(0,w-p)}</strong></div><div><b>Overall Attendance</b><strong>${ap.toFixed(1)}%</strong></div></div>`;printWindow("Student Attendance Report",body)}catch(e){toast(e.message)}}
async function printClassAttendance(){try{const cl=$("attClass").value,sec=$("attSection").value,year=Number($("attYear").value),month=Number($("attMonth").value);if(!cl||!sec){toast("Select class and section first.");return}const d=await api(`/api/attendance/class?class_name=${encodeURIComponent(cl)}&section=${encodeURIComponent(sec)}&year=${year}&month=${month}`);const body=reportHeader("Class Attendance Report",`Class ${cl}-${sec} • ${new Date(2000,month-1,1).toLocaleString("en",{month:"long"})} ${year}`)+`<table><thead><tr><th>Roll</th><th>Admission No.</th><th>Student</th><th class="num">Working Days</th><th class="num">Present</th><th class="num">Absent</th><th class="num">Attendance</th></tr></thead><tbody>${d.students.map(s=>`<tr><td class="num">${s.roll}</td><td>${esc(s.admission_no)}</td><td>${esc(s.name)}</td><td class="num">${s.working_days}</td><td class="num">${s.present_days}</td><td class="num">${Math.max(0,s.working_days-s.present_days)}</td><td class="num">${s.percentage==null?"—":s.percentage+"%"}</td></tr>`).join("")}</tbody></table>`;printWindow("Class Attendance Report",body,true)}catch(e){toast(e.message)}}
async function printStudentDirectory(){try{const list=me.role==="student"?students.filter(s=>s.id===me.student_id):students;const body=reportHeader("Student Directory")+`<table><thead><tr><th>Roll</th><th>Admission No.</th><th>Student</th><th>Class</th><th>Gender</th><th>Parent</th></tr></thead><tbody>${list.map(s=>`<tr><td>${s.roll}</td><td>${esc(s.admission_no)}</td><td>${esc(s.name)}</td><td>${s.class_name}-${s.section}</td><td>${esc(s.gender||"")}</td><td>${esc(s.father_name||s.mother_name||"")}</td></tr>`).join("")}</tbody></table>`;printWindow("Student Directory",body,true)}catch(e){toast(e.message)}}
async function printAnalytics(){try{const list=selectedStudents(),a=await analyticsFor(list);const body=reportHeader("Academic Analytics")+`<div class="summary"><div><b>Students</b><strong>${list.length}</strong></div><div><b>Average Result</b><strong>${a.average==null?"—":a.average.toFixed(1)+"%"}</strong></div><div><b>Attendance</b><strong>${a.attendance==null?"—":a.attendance.toFixed(1)+"%"}</strong></div><div><b>Exams Tracked</b><strong>${config.exams.length}</strong></div></div><table><thead><tr><th>Subject</th><th class="num">Average %</th></tr></thead><tbody>${Object.entries(a.subject||{}).map(([k,v])=>`<tr><td>${esc(k)}</td><td class="num">${Number(v).toFixed(1)}%</td></tr>`).join("")||`<tr><td colspan="2">No academic data.</td></tr>`}</tbody></table>`;printWindow("Academic Analytics",body)}catch(e){toast(e.message)}}
$("printStudentDirectory")?.addEventListener("click",printStudentDirectory);
