$('bulkMarkClass')?.addEventListener('change',fillBulkSections);$('loadBulkMarks')?.addEventListener('click',loadBulkMarks);$('saveBulkMarks')?.addEventListener('click',saveBulkMarks);$('fillBulkBlank')?.addEventListener('click',()=>document.querySelectorAll('#bulkMarksTable .bulk-score').forEach(x=>x.value=''));

const resourceIcons={"Circular":"◈","Home Work":"✓","Time Table":"▦","Tutorials":"▤","Question Bank":"▣","Syllabus":"▤","Co-Curricular":"✦","Date Sheet":"▥","Infirmary":"✚","Communication":"◌","Examination":"▣"};
let resourceCategory="";
async function renderResources(){
 if(!me)return;
 if(!config.resource_categories?.length){let c=await api("/api/config");config=c;}
 const cats=config.resource_categories||[];
 const wrap=$("resourceCategories");
 wrap.innerHTML=`<button class="resource-cat active" data-cat=""><span>▦</span><b>All</b><small>Everything</small></button>`+cats.map(c=>`<button class="resource-cat" data-cat="${esc(c)}"><span>${resourceIcons[c]||"•"}</span><b>${esc(c)}</b><small>School resources</small></button>`).join("");
 wrap.querySelectorAll(".resource-cat").forEach(b=>b.onclick=()=>{resourceCategory=b.dataset.cat;wrap.querySelectorAll(".resource-cat").forEach(x=>x.classList.toggle("active",x===b));loadResources()});
 const scope=$("resourceScope");if(scope){scope.innerHTML=`<option value="">All classes</option>`+Array.from({length:12},(_,i)=>`<option value="${i+1}">Class ${i+1}</option>`).join("");scope.value=scope.value||localStorage.getItem("edutrack.resource.class")||"";scope.onchange=()=>{localStorage.setItem("edutrack.resource.class",scope.value);loadResources()}}
 $("resourceSearch").oninput=loadResources;
 loadResources();
}
async function loadResources(){
 const list=await api(`/api/resources${resourceCategory?`?category=${encodeURIComponent(resourceCategory)}`:""}`);
 const q=($("resourceSearch")?.value||"").toLowerCase();const sc=$("resourceScope")?.value||"";
 const filtered=list.filter(r=>(!q||`${r.title} ${r.description} ${r.category} ${r.original_filename}`.toLowerCase().includes(q))&&(!sc||r.class_name===sc||!r.class_name));
 $("resourceGrid").innerHTML=filtered.map(r=>`<article class="resource-card reveal"><div class="resource-icon">${resourceIcons[r.category]||"•"}</div><div class="resource-meta"><span>${esc(r.category)}</span><time>${new Date(r.created_at.replace(" ","T")+"Z").toLocaleDateString()}</time></div><h3>${esc(r.title)}</h3><p>${esc(r.description||"School academic resource")}</p><div class="resource-scope">${r.class_name?`Class ${esc(r.class_name)}${r.section?`-${esc(r.section)}`:""}`:"All students"}</div><div class="resource-actions"><a class="btn secondary" href="${r.download_url}">↓ Open / Download</a>${me.role!=="student"?`<button class="tiny danger" data-resource-delete="${r.id}">Delete</button>`:""}</div><small class="resource-by">Uploaded by ${esc(r.uploader||"School")}</small></article>`).join("")||`<div class="empty-resource"><div>▦</div><h3>No resources here yet</h3><p>Upload the first ${resourceCategory||"school"} resource.</p></div>`;
 document.querySelectorAll("[data-resource-delete]").forEach(b=>b.onclick=async()=>{if(!confirm("Delete this resource?"))return;try{await api("/api/resources/"+b.dataset.resourceDelete,{method:"DELETE"});loadResources();toast("Resource deleted")}catch(e){toast(e.message)}});
 observeReveals();
}
function openResourceModal(){
 const cats=config.resource_categories||[];
 $("modalContent").innerHTML=`<div class="eyebrow">ACADEMIC HUB</div><h2>Upload a school resource</h2><p>Publish a file for everyone or target a particular class and section.</p><form id="resourceForm"><label>Title<input name="title" required placeholder="e.g. Mathematics Homework — Chapter 4"></label><div class="two"><label>Category<select name="category">${cats.map(c=>`<option>${esc(c)}</option>`).join("")}</select></label><label>Target class<select name="class_name"><option value="">All classes</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}">Class ${i+1}</option>`).join("")}</select></label><label>Section<input name="section" maxlength="4" placeholder="Leave blank for whole class"></label></div><label>Description<textarea name="description" rows="3" placeholder="Short description for students..."></textarea></label><label>File<input name="file" type="file" required accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.jpg,.jpeg,.png,.gif,.txt,.csv,.zip"></label><div class="upload-note">Maximum 25 MB. Allowed: PDF, Word, Excel, PowerPoint, images, TXT, CSV and ZIP.</div><button type="submit" class="btn primary full" id="resourceSubmit">Upload resource</button></form><div id="resourceError" class="error"></div>`;
 $("modal").classList.remove("hidden");

 $("resourceForm").onsubmit=async e=>{
  e.preventDefault();
  const form=e.target, btn=$("resourceSubmit"), err=$("resourceError"), file=form.file.files[0];
  err.textContent="";
  if(!file){err.textContent="Please choose a file.";return}
  if(file.size>25*1024*1024){err.textContent="File is larger than 25 MB.";return}

  const old=btn.innerHTML;
  btn.disabled=true;
  btn.innerHTML="Uploading…";
  try{
   const response=await fetch("/api/resources",{
    method:"POST",
    body:new FormData(form),
    credentials:"same-origin"
   });
   const text=await response.text();
   let data={};
   try{data=JSON.parse(text)}catch(_){}
   if(!response.ok) throw Error(data.error||`Upload failed (HTTP ${response.status}).`);
   if(!data.ok) throw Error(data.error||"The server did not confirm the upload.");

   // Explicit success popup inside the modal.
   $("modalContent").innerHTML=`<div class="success-box"><div class="eyebrow">UPLOAD COMPLETE</div><h2>Resource uploaded successfully</h2><p><strong>${esc(data.filename)}</strong> is now available in the Academic Hub.</p><p class="muted">${esc(data.category)}${data.class_name?` • Class ${esc(data.class_name)}${data.section?`-${esc(data.section)}`:""}`:" • All classes"}</p><button class="btn primary full" id="resourceDone">Done</button></div>`;
   $("resourceDone").onclick=async()=>{
    $("modal").classList.add("hidden");
    await loadResources();
    toast("Resource uploaded successfully");
   };
  }catch(x){
   err.textContent=x.message||"Upload failed. Please try again.";
  }finally{
   if($("resourceSubmit")){$("resourceSubmit").disabled=false;$("resourceSubmit").innerHTML=old}
  }
 };
}

$("uploadResourceBtn")?.addEventListener("click",openResourceModal);

boot();
